import sys
from collections import deque, defaultdict

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def build_tree(nodes):
    if not nodes:
        return None

    root = Node(nodes[0])
    queue = deque([root])
    i = 1

    while queue and i < len(nodes):
        current = queue.popleft()

        if i < len(nodes) and nodes[i] is not None:
            current.left = Node(nodes[i])
            queue.append(current.left)
        i += 1

        if i < len(nodes) and nodes[i] is not None: 
            current.right = Node(nodes[i])
            queue.append(current.right)
        i += 1

    return root

def KDistanceNodes(root, target, k):
    if not root:
        return []

    # Step 1: Create a map to store parent pointers
    parent_map = {}

    def set_parents(node, parent):
        if not node:
            return
        parent_map[node] = parent
        set_parents(node.left, node)
        set_parents(node.right, node)

    set_parents(root, None)

    # Step 2: Find the target node
    target_node = None

    def find_target(node):
        nonlocal target_node
        if not node:
            return
        if node.data == target:
            target_node = node
            return
        find_target(node.left)
        find_target(node.right)

    find_target(root)

    if not target_node:
        return []

    # Step 3: BFS to find nodes at distance k
    visited = set()
    queue = deque([(target_node, 0)])
    result = []

    while queue:
        node, dist = queue.popleft()

        if node in visited:
            continue
        visited.add(node)

        if dist == k:
            result.append(node.data)
            continue

        # Check left child
        if node.left and node.left not in visited:
            queue.append((node.left, dist + 1))

        # Check right child
        if node.right and node.right not in visited:
            queue.append((node.right, dist + 1))

        # Check parent
        if node in parent_map and parent_map[node] and parent_map[node] not in visited:
            queue.append((parent_map[node], dist + 1))

    return sorted(result)

def main():
    try:
        lines = sys.stdin.read().strip().split('\n')
        if not lines:
            return

        # Parse tree structure
        # Format: First line is the tree in level order (None for missing nodes)
        # Second line is target
        # Third line is k

        tree_data_line = lines[0].strip()
        target_line = lines[1].strip() if len(lines) > 1 else ""
        k_line = lines[2].strip() if len(lines) > 2 else ""

        # Parse tree data
        if tree_data_line:
            parts = tree_data_line.split()
            tree_nodes = []
            for p in parts:
                if p == 'None' or p == 'null':
                    tree_nodes.append(None)
                else:
                    tree_nodes.append(int(p))
        else:
            tree_nodes = []

        target = int(target_line) if target_line else 0
        k = int(k_line) if k_line else 0

        root = build_tree(tree_nodes)
        result = KDistanceNodes(root, target, k)

        print(" ".join(map(str, result)))

    except Exception:
        pass

if __name__ == "__main__":
    main()
